const AdmZip = require('adm-zip');
const zip = new AdmZip('testbed/docs/travel_summary.docx');
let xml = zip.readAsText('word/document.xml');

// Update BK-B70889: fix the route from empty to JFK → LHR
const oldText = 'Booking BK-B70889 | user_59b22691 |  →  | business | Status: confirmed';
const newText = 'Booking BK-B70889 | user_59b22691 | JFK → LHR | business | Status: confirmed';

if (xml.includes(oldText)) {
  xml = xml.replace(oldText, newText);
  zip.updateFile('word/document.xml', Buffer.from(xml, 'utf-8'));
  zip.writeZip('testbed/docs/travel_summary.docx');
  console.log('Updated successfully!');
